<script setup>
import { onMounted, reactive, ref } from 'vue'
import { api, allPets, errorMessage, imageUrl, unwrap } from '../api'
const pets = ref([]), error = ref(''), message = ref(''), editor = ref(false), current = ref(null), busy = ref(false)
const form = reactive({ name: '', species: 'dog', breed: '', gender: 'unknown', birth_date: '', weight: '', color: '', description: '' })
async function load() { try { pets.value = await allPets() } catch (e) { error.value = errorMessage(e) } }
onMounted(load)
function open(pet = null) { current.value = pet; Object.assign(form, { name: '', species: 'dog', breed: '', gender: 'unknown', birth_date: '', weight: '', color: '', description: '' }, pet || {}); editor.value = true }
async function save() { busy.value = true; error.value = ''; try { const payload = { ...form, weight: form.weight === '' ? null : Number(form.weight) }; const result = unwrap(current.value ? await api.put(`/pets/${current.value.id}`, payload) : await api.post('/pets', payload)); editor.value = false; message.value = result.message || '宠物档案已保存'; await load() } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
async function remove(pet) { if (!confirm(`确定删除 ${pet.name} 的档案及关联记录吗？`)) return; try { unwrap(await api.delete(`/pets/${pet.id}`)); message.value = '宠物档案已删除'; await load() } catch (e) { error.value = errorMessage(e) } }
async function avatar(pet, event) { const file = event.target.files?.[0]; if (!file) return; const data = new FormData(); data.append('avatar', file); try { unwrap(await api.post(`/pets/${pet.id}/avatar`, data)); await load() } catch (e) { error.value = errorMessage(e) } }
</script>
<template>
  <div class="page-head"><div><h1>我的宠物</h1><p>一个个值得珍藏的成长档案</p></div><button class="btn" @click="open()">＋ 添加宠物</button></div>
  <div v-if="error" class="message error">{{ error }}</div><div v-if="message" class="message">{{ message }}</div>
  <div v-if="pets.length" class="grid"><div v-for="pet in pets" :key="pet.id" class="card"><img v-if="pet.avatar" class="pet-image" :src="imageUrl(pet.avatar)" :alt="pet.name"><div v-else class="pet-placeholder">{{ pet.species === 'cat' ? '🐈' : '🐕' }}</div><h3 style="margin-top:14px">{{ pet.name }}</h3><p class="muted small">{{ pet.breed || '品种未填写' }} · {{ pet.age_display || '年龄未填写' }} · {{ pet.weight ? `${pet.weight} kg` : '体重未填写' }}</p><div class="actions"><RouterLink class="btn secondary" :to="`/pets/${pet.id}/health`">照护档案</RouterLink><button class="btn secondary" @click="open(pet)">编辑</button><button class="btn danger" @click="remove(pet)">删除</button></div><label class="small muted" style="display:block;margin-top:12px">更换照片 <input type="file" accept="image/*" style="max-width:100%" @change="avatar(pet,$event)"></label></div></div><div v-else class="empty">您还没有添加宠物。点击“添加宠物”开始记录。</div>
  <div v-if="editor" class="modal-backdrop" @click.self="editor=false"><form class="modal" @submit.prevent="save"><div class="page-head"><h2>{{ current ? '编辑宠物' : '添加宠物' }}</h2><button type="button" class="text-button" @click="editor=false">关闭 ✕</button></div><div class="form-grid"><label class="field"><span>昵称 *</span><input v-model.trim="form.name" required maxlength="64"></label><label class="field"><span>种类 *</span><select v-model="form.species"><option value="dog">狗狗</option><option value="cat">猫咪</option></select></label><label class="field"><span>品种</span><input v-model.trim="form.breed"></label><label class="field"><span>性别</span><select v-model="form.gender"><option value="unknown">未知</option><option value="male">公</option><option value="female">母</option></select></label><label class="field"><span>出生日期</span><input v-model="form.birth_date" type="date"></label><label class="field"><span>体重 (kg)</span><input v-model="form.weight" type="number" min="0" step="0.01"></label><label class="field"><span>毛色</span><input v-model="form.color"></label><label class="field full"><span>关于它</span><textarea v-model="form.description" placeholder="写下它的性格和故事…"></textarea></label></div><div class="actions"><button class="btn" :disabled="busy">保存档案</button></div></form></div>
</template>
